const D = { density: .5, energy: .65, scale: 1, speed: 1, hue: 30, gravity: .5, decay: .5, style: 'phosphor', act: 'finale', seed: 0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const TAU = Math.PI * 2;
const fr = i => { const q = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return q - Math.floor(q); };
const hw = h => ((h % 360) + 360) % 360;
const u = Math.min(width, height);
const sty = P.style;
const t = K.t;

if (!S.fw) S.fw = { rockets: [], sparks: [], smoke: [], last: -999 };
const F = S.fw;

// ---- beat-launched rockets (guard t0 reset) ----
const bi = Math.floor(K.beat);
if (S.lastBi == null || bi < S.lastBi) S.lastBi = bi - 1;
const every = P.density > 0.66 ? 1 : (P.density > 0.33 ? 2 : 4);
const sec = ((Math.floor(K.section) % 8) + 8) % 8;
const ACT = {
  finale: { rate: 1, size: 1 + 0.5 * (sec >= 6 ? 1 : 0), spread: 1 },
  volley: { rate: 1, size: 1, spread: 1.5 },
  ember:  { rate: 0.5, size: 0.7, spread: 0.7 } };
const ac = ACT[P.act] || ACT.finale;

if (bi > S.lastBi) {
  const launches = (bi % every === 0) ? 1 : 0;
  const extra = (ac.rate > 0.9 && K.intensity > 0.6 && bi % 2 === 0) ? 1 : 0;
  for (let L = 0; L < launches + extra; L++) {
    if (F.rockets.length < 8) {
      const rr = fr(bi * 7 + L * 13);
      F.rockets.push({
        x: width * (0.15 + rr * 0.7),
        y: height * 1.02,
        ty: height * (0.12 + fr(bi * 5 + L * 3) * 0.36),
        vx: (fr(bi * 3 + L) - 0.5) * u * 0.004,
        hue: hw(P.hue + (fr(bi + L * 9) - 0.5) * 120),
        big: 0.7 + fr(bi * 2 + L) * 0.7 });
    }
  }
  S.lastBi = bi;
}

const add = (sty === 'phosphor' || sty === 'thermal' || sty === 'pixel');
const grav = (0.03 + P.gravity * 0.12) * u * 0.006;
const fade = 0.006 + P.decay * 0.03;
const inten = 0.5 + 0.5 * K.intensity;

push();
noStroke();
if (add) blendMode(ADD);

// ---- continuous drifting ember-rain floor (real-time motion floor, never re-phases) ----
const nem = Math.floor(90 + P.density * 150);
for (let i = 0; i < nem; i++) {
  const spd = 0.06 + 0.13 * fr(i + 201);
  const life = (((fr(i * 2 + 200) + t * spd) % 1) + 1) % 1;
  const ex = ((((fr(i * 3 + 202) + Math.sin(t * 0.25 + i) * 0.03) % 1) + 1) % 1) * width;
  const ey = life * height;
  const flick = 0.5 + 0.5 * Math.sin(t * 6 + i * 1.7);
  const eh = hw(P.hue + (fr(i + 203) - 0.5) * 60);
  const ea = (0.4 + 0.6 * (1 - life)) * (18 + 16 * flick) * (0.5 + 0.5 * P.energy);
  const es = u * 0.011 * (0.7 + flick) * P.scale;
  if (sty === 'blueprint') {
    stroke(hw(P.hue + 180), 22, 100, ea * 0.7); strokeWeight(1); noFill();
    ellipse(ex, ey, es * 0.9, es * 0.9);
    line(ex, ey - es, ex, ey - es * 2.4); noStroke();
  } else {
    if (sty === 'ink') fill(hw(P.hue), 14, 44, ea * 0.95);
    else if (sty === 'thermal') fill(hw(20 + life * 45), 90, 100, ea);
    else fill(eh, 65, 100, ea);
    ellipse(ex, ey, es, es);
    if (sty === 'ink') fill(hw(P.hue), 14, 44, ea * 0.5);
    else if (sty === 'thermal') fill(hw(20 + life * 45), 80, 100, ea * 0.45);
    else fill(eh, 55, 100, ea * 0.45);
    ellipse(ex, ey - es * 1.7, es * 0.6, es * 1.3);
  }
}

// ---- rockets ----
for (let i = F.rockets.length - 1; i >= 0; i--) {
  const r = F.rockets[i];
  const rise = u * (0.012 + 0.01 * P.energy) * P.speed * (1.2 - 0.4 * K.phase);
  r.y -= rise; r.x += r.vx;
  if (sty === 'blueprint') {
    stroke(hw(P.hue + 180), 20, 100, 55); strokeWeight(1); noFill();
    line(r.x, r.y, r.x, Math.min(height * 1.02, r.y + rise * 4)); noStroke();
  } else if (sty === 'ink') {
    fill(hw(P.hue), 12, 18, 70); ellipse(r.x, r.y, u * 0.008, u * 0.016);
  } else {
    fill(r.hue, 55, 100, 55); ellipse(r.x, r.y, u * 0.006, u * 0.014);
  }
  if (r.y <= r.ty) {
    const cnt = Math.floor((22 + 34 * P.energy) * ac.size);
    const burstV = u * (0.004 + 0.007 * P.energy) * ac.size;
    for (let k = 0; k < cnt; k++) {
      if (F.sparks.length > 340) break;
      const an = (k / cnt) * TAU + fr(k + r.x) * 0.4;
      const sp = burstV * (0.5 + fr(k * 2 + 7) * 0.7) * ac.spread;
      F.sparks.push({ x: r.x, y: r.y, vx: Math.cos(an) * sp, vy: Math.sin(an) * sp,
        hue: r.hue, life: 1, r0: r.ty });
    }
    F.smoke.push({ x: r.x, y: r.y, r: u * 0.02, life: 1, hue: r.hue });
    F.rockets.splice(i, 1);
  }
}

// ---- smoke puffs (drift up + fade) ----
for (let i = F.smoke.length - 1; i >= 0; i--) {
  const m = F.smoke[i];
  m.y -= u * 0.0012; m.r += u * 0.0016; m.life -= 0.012;
  if (m.life <= 0) { F.smoke.splice(i, 1); continue; }
  if (sty === 'blueprint' || sty === 'phosphor') continue;
  fill(sty === 'ink' ? hw(P.hue) : hw(m.hue + 20), sty === 'ink' ? 8 : 18, sty === 'ink' ? 26 : 40, m.life * 10);
  ellipse(m.x, m.y, m.r, m.r);
}

// ---- sparks ----
for (let i = F.sparks.length - 1; i >= 0; i--) {
  const p = F.sparks[i];
  p.x += p.vx * P.speed; p.y += p.vy * P.speed; p.vy += grav; p.vx *= 0.992;
  p.life -= fade;
  if (p.life <= 0 || p.y > height * 1.1) { F.sparks.splice(i, 1); continue; }
  const tw = 0.6 + 0.4 * Math.sin(t * 9 + p.x);
  const al = p.life * (26 + A.treble * 20) * tw;
  const sz = u * 0.006 * P.scale * (0.5 + p.life * 0.9);
  if (sty === 'blueprint') {
    stroke(hw(P.hue + 180 + (1 - p.life) * 40), 24, 100, al * 1.4); strokeWeight(1); noFill();
    ellipse(p.x, p.y, sz * 2, sz * 2); noStroke();
  } else if (sty === 'ink') {
    fill(hw(P.hue), 14, 16, al * 1.2); ellipse(p.x, p.y, sz, sz);
  } else if (sty === 'thermal') {
    const heat = p.life;
    fill(hw(60 - heat * 60), 90, 100, al); ellipse(p.x, p.y, sz, sz);
  } else if (sty === 'pixel') {
    const g = u * 0.014 * P.scale;
    const gx = Math.round(p.x / g) * g, gy = Math.round(p.y / g) * g;
    fill(p.hue, 70, 100, al); rect(gx, gy, g * 0.8, g * 0.8);
  } else {
    // phosphor — glowing trail head
    fill(p.hue, 45, 100, al * 0.7); ellipse(p.x, p.y, sz * 2.2, sz * 2.2);
    fill(hw(p.hue + 15), 20, 100, al); ellipse(p.x, p.y, sz, sz);
  }
}

if (add) blendMode(BLEND);
pop();
drawingContext.shadowBlur = 0;
